rule brain_database_account_modification_local {
  meta:
    author = "Security Analytics Team"
    description = "Detects MSSQL and Postgres database account modification events generated locally by BRAIN/BRAIN_MSSQL content."
    severity = "MEDIUM"
    source = "QRadar (LOCAL detections)"
    created = "2025-11-26"
    version = "1.0"
    tags = ["database", "account_modification", "MSSQL", "Postgres", "BRAIN", "QRadar", "LOCAL"]

  events:
    // Access security_result.detection_fields via map-style indexing: ["key"]
    // If a key is missing, the expression evaluates to null, which safely fails comparisons.
    $sr where
      $sr.metadata.event_type = "SECURITY_RESULT" and
      $sr.security_result.detection_fields["detection_source"] = "LOCAL" and
      $sr.security_result.detection_fields["detecting_product"] in ("BRAIN", "BRAIN_MSSQL") and
      $sr.security_result.detection_fields["event_category"] in ("BB:MSSQL Account Modification", "BB:TDV Postgres Account Modification")
      // Optional allowlist to reduce benign positives (keep commented to preserve current detection semantics).
      // To enable, create a Chronicle reference list with known service/admin accounts and uncomment below:
      // and not coalesce($sr.principal.user.userid, $sr.principal.user.email, $sr.security_result.detection_fields["actor_user"])
      //     in list("Service and Admin Accounts Allowlist")

  match:
    $sr

  options:
    // Suppress duplicate alerts for repeated local detections by same host/signature/target/action
    // Coalesce critical fields to avoid nulls in the suppression key
    suppression_window = 30m
    suppression_key = concat(
      coalesce($sr.target.hostname, $sr.security_result.detection_fields["host"], $sr.principal.hostname, "<unknown_host>"), "|",
      $sr.security_result.detection_fields["event_category"], "|",
      coalesce($sr.security_result.detection_fields["target_account"], "<missing>"), "|",
      coalesce($sr.security_result.detection_fields["action"], "<missing>")
    )

  output:
    // Constant detection title per IR
    detection_title = "BRAIN Database Account Modification",

    // Core timestamps
    timestamp = $sr.metadata.event_timestamp,

    // Product / source / signature
    product = $sr.security_result.detection_fields["detecting_product"],
    detection_source = $sr.security_result.detection_fields["detection_source"],
    signature = $sr.security_result.detection_fields["event_category"],

    // Database context
    db_type = $sr.security_result.detection_fields["db_type"],
    db_instance = $sr.security_result.detection_fields["db_instance"],

    // Normalize host resolution with additional fallback and default literal
    host = coalesce($sr.target.hostname, $sr.security_result.detection_fields["host"], $sr.principal.hostname, "<unknown_host>"),

    // Actor / target and action
    actor_user = coalesce($sr.principal.user.userid, $sr.principal.user.email, $sr.security_result.detection_fields["actor_user"]),
    target_account = coalesce($sr.security_result.detection_fields["target_account"], "<missing>"),
    action = coalesce($sr.security_result.detection_fields["action"], "<missing>"),

    // Enrichment via AAAA EDS reference data (join on asset_id OR host)
    asset_criticality = coalesce(
      lookup_table_value("AAAA EDS", "asset_id", $sr.target.asset_id, "asset_criticality"),
      lookup_table_value("AAAA EDS", "host", coalesce($sr.target.hostname, $sr.security_result.detection_fields["host"], $sr.principal.hostname), "asset_criticality")
    ),
    asset_owner = coalesce(
      lookup_table_value("AAAA EDS", "asset_id", $sr.target.asset_id, "owner"),
      lookup_table_value("AAAA EDS", "host", coalesce($sr.target.hostname, $sr.security_result.detection_fields["host"], $sr.principal.hostname), "owner")
    )

  over 1h
}

